import{_ as r,C as s,o as a,c as o,a0 as t,b as l,w as i,a as c,E as d,a1 as u}from"./chunks/framework.DYS8d9tm.js";const E=JSON.parse('{"title":"Email Ingestion & Hardened Sync System","description":"","frontmatter":{},"headers":[],"relativePath":"technical/data ingestion/email_ingestion.md","filePath":"technical/data ingestion/email_ingestion.md"}'),h={name:"technical/data ingestion/email_ingestion.md"};function m(p,e,g,S,A,P){const n=s("Mermaid");return a(),o("div",null,[e[1]||(e[1]=t('<h1 id="email-ingestion-hardened-sync-system" tabindex="-1">Email Ingestion &amp; Hardened Sync System <a class="header-anchor" href="#email-ingestion-hardened-sync-system" aria-label="Permalink to &quot;Email Ingestion &amp; Hardened Sync System&quot;">​</a></h1><h2 id="_1-executive-summary" tabindex="-1">1. Executive Summary <a class="header-anchor" href="#_1-executive-summary" aria-label="Permalink to &quot;1. Executive Summary&quot;">​</a></h2><p>The Email Ingestion System provides a high-reliability bridge between financial email sources (bank alerts, statements) and the core finance engine. This document serves as both the architectural overview and technical specification for the hardened sync pipeline.</p><h2 id="_2-architecture-data-flow" tabindex="-1">2. Architecture &amp; Data Flow <a class="header-anchor" href="#_2-architecture-data-flow" aria-label="Permalink to &quot;2. Architecture &amp; Data Flow&quot;">​</a></h2>',4)),(a(),l(u,null,{default:i(()=>[d(n,{id:"mermaid-12",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20UI%20as%20Frontend%20(EmailSettings.vue)%0A%20%20%20%20participant%20API%20as%20Backend%20API%20(router.py)%0A%20%20%20%20participant%20SCH%20as%20Scheduler%20(scheduler.py)%0A%20%20%20%20participant%20ESS%20as%20EmailSyncService%0A%20%20%20%20participant%20SP%20as%20StatementProcessor%0A%20%20%20%20participant%20PS%20as%20External%20Parser%20Service%0A%20%20%20%20participant%20DB%20as%20Database%20(EmailSyncLog)%0A%0A%20%20%20%20rect%20rgb(240%2C%20248%2C%20255)%0A%20%20%20%20Note%20over%20UI%2C%20API%3A%20User%20Interaction%0A%20%20%20%20UI-%3E%3EAPI%3A%20POST%20%2Femail%2Fsync%2F%7Bid%7D%0A%20%20%20%20API--%3E%3EUI%3A%20200%20OK%20(Status%3A%20Started)%0A%20%20%20%20end%0A%0A%20%20%20%20par%20Background%20Execution%20(Transactions)%0A%20%20%20%20%20%20%20%20API-%3E%3EESS%3A%20sync_emails()%0A%20%20%20%20%20%20%20%20ESS-%3E%3EESS%3A%20Fetch%20IMAP%20UIDs%0A%20%20%20%20%20%20%20%20ESS-%3E%3EESS%3A%20Clean%20HTML%20(Preserve%20%5Cn)%0A%20%20%20%20%20%20%20%20ESS-%3E%3EPS%3A%20Batch%20Parse%0A%20%20%20%20%20%20%20%20PS--%3E%3EESS%3A%20Results%0A%20%20%20%20%20%20%20%20ESS-%3E%3EDB%3A%20Log%20Detailed%20JSON%0A%20%20%20%20and%20Background%20Execution%20(Statements)%0A%20%20%20%20%20%20%20%20API-%3E%3ESP%3A%20sync_statements()%0A%20%20%20%20%20%20%20%20SP-%3E%3ESP%3A%20Broad%20IMAP%20Search%0A%20%20%20%20%20%20%20%20SP-%3E%3ESP%3A%20Extract%20PDF%0A%20%20%20%20%20%20%20%20SP-%3E%3EPS%3A%20Parse%20Statement%0A%20%20%20%20%20%20%20%20SP-%3E%3EDB%3A%20Log%20Detailed%20JSON%0A%20%20%20%20end%0A%0A%20%20%20%20UI-%3E%3EDB%3A%20Fetch%20Recent%20Logs%0A%20%20%20%20DB--%3E%3EUI%3A%20JSON%20Data%0A%20%20%20%20UI-%3E%3EUI%3A%20Render%20%22Scan%20Details%22%20Cards%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="_3-technical-specifications" tabindex="-1">3. Technical Specifications <a class="header-anchor" href="#_3-technical-specifications" aria-label="Permalink to &quot;3. Technical Specifications&quot;">​</a></h2><h3 id="_3-1-imap-stability-uid-based-sync" tabindex="-1">3.1 IMAP Stability (UID-Based Sync) <a class="header-anchor" href="#_3-1-imap-stability-uid-based-sync" aria-label="Permalink to &quot;3.1 IMAP Stability (UID-Based Sync)&quot;">​</a></h3><p>Standard IMAP sequence numbers are volatile and reset upon mailbox re-indexing. The system now uses <strong>IMAP UIDs</strong>, which are persistent unique identifiers. This ensures that the system&#39;s &quot;last synced&quot; pointer remains accurate even if the user moves or deletes emails in their provider&#39;s UI.</p><h3 id="_3-2-html-cleaning-preserving-structural-layout" tabindex="-1">3.2 HTML Cleaning (Preserving Structural Layout) <a class="header-anchor" href="#_3-2-html-cleaning-preserving-structural-layout" aria-label="Permalink to &quot;3.2 HTML Cleaning (Preserving Structural Layout)&quot;">​</a></h3><p>Bank emails often use complex nested tables. Aggressive tag-stripping typically results in a single-line string that regex parsers cannot process.</p><ul><li><strong>Solution</strong>: The cleaner replaces <code>&lt;tr&gt;</code>, <code>&lt;br&gt;</code>, <code>&lt;p&gt;</code>, and <code>&lt;div&gt;</code> tags with <code>\\n</code> before stripping remaining HTML.</li><li><strong>Result</strong>: Preserves the vertical alignment of transaction data (Date/Amount/Description), allowing pattern-matching to succeed.</li></ul><h3 id="_3-3-sender-normalization-routing" tabindex="-1">3.3 Sender Normalization &amp; Routing <a class="header-anchor" href="#_3-3-sender-normalization-routing" aria-label="Permalink to &quot;3.3 Sender Normalization &amp; Routing&quot;">​</a></h3><p>Email &quot;From&quot; headers are normalized to a clean format (lowercase email only) to ensure reliable routing to custom bank-specific parsers:</p><ul><li><strong>Raw</strong>: <code>HDFC Bank &lt;alerts@hdfcbank.net&gt;</code></li><li><strong>Normalized</strong>: <code>alerts@hdfcbank.net</code></li></ul><h2 id="_4-observability-recent-scan-activity" tabindex="-1">4. Observability (Recent Scan Activity) <a class="header-anchor" href="#_4-observability-recent-scan-activity" aria-label="Permalink to &quot;4. Observability (Recent Scan Activity)&quot;">​</a></h2><p>The system provides granular transparency into every email processed.</p><h3 id="_4-1-log-hierarchy" tabindex="-1">4.1 Log Hierarchy <a class="header-anchor" href="#_4-1-log-hierarchy" aria-label="Permalink to &quot;4.1 Log Hierarchy&quot;">​</a></h3><ul><li><strong>EmailSyncLog</strong>: Records the overall session (start time, status, total items).</li><li><strong>EmailSyncItemLog</strong>: Records the result for each individual email.</li></ul><h3 id="_4-2-data-points-captured" tabindex="-1">4.2 Data Points Captured <a class="header-anchor" href="#_4-2-data-points-captured" aria-label="Permalink to &quot;4.2 Data Points Captured&quot;">​</a></h3><ul><li><strong>Parser Used</strong>: Identifies if a Bank-specific, Pattern, or AI parser was successful.</li><li><strong>Status</strong>: Processed, Failed, or Skipped.</li><li><strong>Reason</strong>: Detailed explanation for the status.</li><li><strong>Transaction Link</strong>: Direct ID link to the <code>PendingTransaction</code>.</li></ul><h2 id="_5-unified-parsing-pipeline" tabindex="-1">5. Unified Parsing Pipeline <a class="header-anchor" href="#_5-unified-parsing-pipeline" aria-label="Permalink to &quot;5. Unified Parsing Pipeline&quot;">​</a></h2><p>Email ingestion follows the <a href="./unified_parsing_pipeline.html">Unified Parsing Pipeline</a> priority:</p><ol><li>Registered Bank Parsers</li><li>DB Regex Patterns</li><li>AI Fallback</li></ol><p>Both <strong>Transaction Alerts</strong> and <strong>Statement PDFs</strong> share this underlying extraction engine to ensure consistency across all data sources.</p>',19))])}const _=r(h,[["render",m]]);export{E as __pageData,_ as default};
